actions.script:
const step = (name, run) => {
    ec.message.pushErrors()
    try { run(); if (ec.message.hasError()) throw new Error(ec.message.getErrorsString()) }
    catch (err) { ec.logger.error(`Billing demo: ${name} not loaded: ${err && err.message ? err.message : err}`) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (!ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'SUPP').one()) { ec.logger.warn('The billing demo needs the project SUPP; nothing loaded'); return }
    if (ec.entity.find('mantle.work.effort.WorkEffortInvoice').condition('workEffortId', 'SUPP').count()) { ec.logger.info('The billing demo is already loaded'); return }
    step('SUPP rates found again', () => ec.service.sync().name('mantle.work.TimeServices.resetAndGet#ProjectTimeEntryRates').parameters({rootWorkEffortId: 'SUPP'}).call())
    step('the invoice of the approved week', () => ec.service.sync().name('mantle.account.InvoiceServices.create#ProjectInvoiceItems').parameters({workEffortId: 'SUPP',
        approvedOnly: true, billableOnly: true, entryGrouping: 'worker', settlementTermId: 'Net30'}).call())
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
